export const DEFAULT_MAX_LINES = 2000;
export const DEFAULT_MAX_BYTES = 50 * 1024; // 50KB
export const GREP_MAX_LINE_LENGTH = 500; // Max chars per grep match line

/** Result metadata for content truncated by line count, byte count, or both. */
export interface TruncationResult {
  /** The truncated content */
  content: string;
  /** Whether truncation occurred */
  truncated: boolean;
  /** Which limit was hit: "lines", "bytes", or null if not truncated */
  truncatedBy: "lines" | "bytes" | null;
  /** Total number of lines in the original content */
  totalLines: number;
  /** Total number of bytes in the original content */
  totalBytes: number;
  /** Number of complete lines in the truncated output */
  outputLines: number;
  /** Number of bytes in the truncated output */
  outputBytes: number;
  /** Whether the last line was partially truncated (only for tail truncation edge case) */
  lastLinePartial: boolean;
  /** Whether the first line exceeded the byte limit (for head truncation) */
  firstLineExceedsLimit: boolean;
  /** The max lines limit that was applied */
  maxLines: number;
  /** The max bytes limit that was applied */
  maxBytes: number;
}

/** Byte and line ceilings used by the truncation helpers. */
export interface TruncationOptions {
  /** Maximum number of lines (default: 2000) */
  maxLines?: number;
  /** Maximum number of bytes (default: 50KB) */
  maxBytes?: number;
}

type ResolvedTruncationInput = ReturnType<typeof resolveTruncationInput>;

interface RuntimeBuffer {
  byteLength(content: string, encoding: "utf8"): number;
  from(content: string, encoding: "utf16le"): { toString(encoding: "utf16le"): string };
}

const runtimeBuffer = (globalThis as { Buffer?: RuntimeBuffer }).Buffer;

function copyString(content: string): string {
  // Copy selected code units without normalizing lone surrogates or retaining the source backing.
  return runtimeBuffer ? runtimeBuffer.from(content, "utf16le").toString("utf16le") : content;
}

function findFirstNonAscii(content: string): number {
  for (let index = 0; index < content.length; index++) {
    if (content.charCodeAt(index) > 0x7f) {
      return index;
    }
  }
  return -1;
}

function utf8ByteLength(content: string): number {
  if (runtimeBuffer) {
    return runtimeBuffer.byteLength(content, "utf8");
  }

  const firstNonAscii = findFirstNonAscii(content);
  if (firstNonAscii === -1) {
    return content.length;
  }

  let bytes = firstNonAscii;
  for (let i = firstNonAscii; i < content.length; i++) {
    const code = content.charCodeAt(i);
    if (code <= 0x7f) {
      bytes += 1;
    } else if (code <= 0x7ff) {
      bytes += 2;
    } else if (code >= 0xd800 && code <= 0xdbff && i + 1 < content.length) {
      const next = content.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        bytes += 4;
        i++;
      } else {
        bytes += 3;
      }
    } else {
      bytes += 3;
    }
  }
  return bytes;
}

/**
 * Format byte counts for compact tool-output diagnostics.
 */
export function formatSize(bytes: number): string {
  if (bytes < 1024) {
    return `${bytes}B`;
  } else if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)}KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
}

function resolveTruncationInput(content: string, options: TruncationOptions) {
  let totalLines = content.length > 0 && !content.endsWith("\n") ? 1 : 0;
  for (let index = content.indexOf("\n"); index !== -1; index = content.indexOf("\n", index + 1)) {
    totalLines++;
  }
  return {
    totalLines,
    totalBytes: utf8ByteLength(content),
    maxLines: options.maxLines ?? DEFAULT_MAX_LINES,
    maxBytes: options.maxBytes ?? DEFAULT_MAX_BYTES,
  };
}

function buildTruncationResult(
  input: ResolvedTruncationInput,
  params: {
    content: string;
    truncatedBy?: TruncationResult["truncatedBy"];
    outputLines?: number;
    outputBytes?: number;
    lastLinePartial?: boolean;
    firstLineExceedsLimit?: boolean;
  },
): TruncationResult {
  let truncatedBy = params.truncatedBy ?? null;
  const outputLines = params.outputLines ?? input.totalLines;
  const outputBytes = params.outputBytes ?? input.totalBytes;
  if (
    !params.firstLineExceedsLimit &&
    input.totalLines > input.maxLines &&
    outputLines >= input.maxLines &&
    outputBytes <= input.maxBytes
  ) {
    truncatedBy = "lines";
  }
  const truncated = truncatedBy !== null;
  return {
    // One-element joins can retain a source slice; multiline joins build their own text.
    content: truncated && outputLines === 1 ? copyString(params.content) : params.content,
    truncated,
    truncatedBy,
    totalLines: input.totalLines,
    totalBytes: input.totalBytes,
    outputLines,
    outputBytes,
    lastLinePartial: params.lastLinePartial ?? false,
    firstLineExceedsLimit: params.firstLineExceedsLimit ?? false,
    maxLines: input.maxLines,
    maxBytes: input.maxBytes,
  };
}

/**
 * Keep the beginning of content while respecting independent line and byte ceilings.
 *
 * Head truncation preserves complete lines; a first line that exceeds the byte
 * ceiling produces empty output and sets firstLineExceedsLimit.
 */
export function truncateHead(content: string, options: TruncationOptions = {}): TruncationResult {
  const input = resolveTruncationInput(content, options);

  if (input.totalLines <= input.maxLines && input.totalBytes <= input.maxBytes) {
    return buildTruncationResult(input, { content });
  }

  const firstLineEnd = content.indexOf("\n");
  const firstLine = content.slice(0, firstLineEnd === -1 ? content.length : firstLineEnd);
  if (input.totalLines > 0 && utf8ByteLength(firstLine) > input.maxBytes) {
    return buildTruncationResult(input, {
      content: "",
      truncatedBy: "bytes",
      outputLines: 0,
      outputBytes: 0,
      firstLineExceedsLimit: true,
    });
  }

  const outputLines: string[] = [];
  let outputBytesCount = 0;
  let truncatedBy: "lines" | "bytes" = input.totalLines > input.maxLines ? "lines" : "bytes";
  // Preserve slice(0, maxLines) semantics for negative and fractional ceilings.
  const lineLimit = Math.trunc(input.maxLines) || 0;
  const selectedLines = Math.min(
    input.totalLines,
    lineLimit < 0 ? input.totalLines + lineLimit : lineLimit,
  );
  for (let start = 0; outputLines.length < selectedLines;) {
    const newline = content.indexOf("\n", start);
    const end = newline === -1 ? content.length : newline;
    const line = content.slice(start, end);
    const lineBytes = utf8ByteLength(line) + (outputLines.length > 0 ? 1 : 0);

    if (outputBytesCount + lineBytes > input.maxBytes) {
      truncatedBy = "bytes";
      break;
    }

    outputLines.push(line);
    start = end + 1;
    outputBytesCount += lineBytes;
  }

  return buildTruncationResult(input, {
    content: outputLines.join("\n"),
    truncatedBy,
    outputLines: outputLines.length,
    outputBytes: outputBytesCount,
  });
}

/**
 * Keep the end of content while respecting independent line and byte ceilings.
 *
 * Tail truncation preserves recent output for command errors and may keep a
 * partial first line when one final line alone exceeds the byte ceiling.
 */
export function truncateTail(content: string, options: TruncationOptions = {}): TruncationResult {
  const input = resolveTruncationInput(content, options);

  if (input.totalLines <= input.maxLines && input.totalBytes <= input.maxBytes) {
    return buildTruncationResult(input, { content });
  }

  const outputLines: string[] = [];
  let outputBytesCount = 0;
  let truncatedBy: "lines" | "bytes" = input.totalLines > input.maxLines ? "lines" : "bytes";
  let lastLinePartial = false;
  // A final newline terminates the last display line; truncated output omits it.
  let end = content.length - (content.endsWith("\n") ? 1 : 0);

  while (outputLines.length < input.totalLines && outputLines.length < input.maxLines) {
    const start = end > 0 ? content.lastIndexOf("\n", end - 1) + 1 : 0;
    const line = content.slice(start, end);
    const lineBytes = utf8ByteLength(line) + (outputLines.length > 0 ? 1 : 0); // +1 for newline

    if (outputBytesCount + lineBytes > input.maxBytes) {
      truncatedBy = "bytes";
      if (outputLines.length === 0) {
        const partialLine = truncateStringToBytesFromEnd(line, input.maxBytes);
        outputLines.push(partialLine);
        outputBytesCount = utf8ByteLength(partialLine);
        lastLinePartial = true;
      }
      break;
    }

    outputLines.push(line);
    end = start - 1;
    outputBytesCount += lineBytes;
  }

  return buildTruncationResult(input, {
    // Join only selected lines so a multiline result does not retain the full source.
    content: outputLines.toReversed().join("\n"),
    truncatedBy,
    outputLines: outputLines.length,
    outputBytes: outputBytesCount,
    lastLinePartial,
  });
}

/**
 * Truncate a string to fit within a byte limit (from the end).
 * Handles multi-byte UTF-8 characters correctly.
 */
function truncateStringToBytesFromEnd(str: string, maxBytes: number): string {
  if (maxBytes <= 0) {
    return "";
  }

  let outputBytes = 0;
  let start = str.length;
  let unchangedEnd = str.length;
  let repairedTail = "";
  for (let i = str.length; i > 0;) {
    let characterStart = i - 1;
    const code = str.charCodeAt(characterStart);
    let characterBytes: number;
    let unpairedSurrogate = false;
    if (code >= 0xdc00 && code <= 0xdfff && characterStart > 0) {
      const previous = str.charCodeAt(characterStart - 1);
      if (previous >= 0xd800 && previous <= 0xdbff) {
        characterStart--;
        characterBytes = 4;
      } else {
        characterBytes = 3;
        unpairedSurrogate = true;
      }
    } else if (code >= 0xd800 && code <= 0xdfff) {
      characterBytes = 3;
      unpairedSurrogate = true;
    } else {
      characterBytes = code <= 0x7f ? 1 : code <= 0x7ff ? 2 : 3;
    }
    if (outputBytes + characterBytes > maxBytes) {
      break;
    }
    outputBytes += characterBytes;
    start = characterStart;
    if (unpairedSurrogate) {
      // Selection already identified the lone surrogate; retain the valid span to its right.
      repairedTail = "\uFFFD" + str.slice(i, unchangedEnd) + repairedTail;
      unchangedEnd = characterStart;
    }
    i = characterStart;
  }

  return str.slice(start, unchangedEnd) + repairedTail;
}

/**
 * Trim a single display line and mark it with the grep-style truncation suffix.
 *
 * The cut point is backed off by one code unit when it would otherwise split a
 * surrogate pair, so emoji / CJK Extension B characters crossing the boundary
 * stay intact instead of rendering as replacement characters.
 */
export function truncateLine(
  line: string,
  maxChars: number = GREP_MAX_LINE_LENGTH,
): { text: string; wasTruncated: boolean } {
  if (line.length <= maxChars) {
    return { text: line, wasTruncated: false };
  }
  let cut = maxChars;
  // Avoid splitting a surrogate pair at the truncation boundary.
  if (cut < line.length) {
    const lastCode = line.charCodeAt(cut - 1);
    if (lastCode >= 0xd800 && lastCode <= 0xdbff) {
      const nextCode = line.charCodeAt(cut);
      if (nextCode >= 0xdc00 && nextCode <= 0xdfff) {
        cut -= 1;
      }
    }
  }
  return { text: `${copyString(line.slice(0, cut))}... [truncated]`, wasTruncated: true };
}

/**
 * Shared CJK-aware character counting for approximate token estimates.
 *
 * This is a provider-independent budget heuristic, not an exact tokenizer.
 * Weighting common CJK, rare BMP characters, width-compatibility forms, and
 * supplementary ideographs separately keeps current tokenizers within a
 * conservative budget range while preserving the existing Latin behavior.
 */

export const CHARS_PER_TOKEN_ESTIMATE = 4;

export type StringCharBudgetOptions = { minimumRawWeight?: number };
const DEFAULT_BUDGET_OPTIONS: StringCharBudgetOptions = {};
const ASCII_RUN_OR_NON_ASCII_CODE_POINT_RE = /[\p{ASCII}]+|[^\p{ASCII}]/gu;

const WEIGHTED_CJK_RANGES = [
  [
    [0x00b7, 0x00b7],
    [0x3000, 0x319f],
    [0x4e00, 0x9fa5],
    [0xac00, 0xd7af],
    [0xff01, 0xff60],
  ],
  [
    [0x1100, 0x11ff],
    [0x2e80, 0x2fff],
    [0x31a0, 0x4dff],
    [0x9fa6, 0x9fff],
    [0xa000, 0xa4ff],
    [0xa700, 0xa707],
    [0xa960, 0xa97f],
    [0xd7b0, 0xd7ff],
    [0xf900, 0xfaff],
  ],
  [
    [0x02c7, 0x02c7],
    [0x02c9, 0x02cb],
    [0x02d9, 0x02d9],
    [0x02ea, 0x02eb],
    [0x0305, 0x0305],
    [0x0323, 0x0323],
    [0xfe10, 0xfe4f],
    [0xff61, 0xffdc],
    [0xffe0, 0xffe6],
  ],
  [[0x1d360, 0x1d371]],
  [
    [0x16fe0, 0x16fff],
    [0x1aff0, 0x1afff],
    [0x1b000, 0x1b16f],
    [0x1f200, 0x1f2ff],
    [0x20000, 0x2fa1f],
    [0x30000, 0x3347f],
  ],
] as const;

const WEIGHTED_CJK_RE = new RegExp(
  `[${WEIGHTED_CJK_RANGES.flatMap((ranges) =>
    ranges.map(([start, end]) => `\\u{${start.toString(16)}}-\\u{${end.toString(16)}}`),
  ).join("")}]`,
  "u",
);

// A fixed 205 KiB lookup avoids rescanning multilingual text for each weight.
const CJK_CATEGORY: Readonly<ArrayLike<number>> = (() => {
  const maxCodePoint = Math.max(
    ...WEIGHTED_CJK_RANGES.flatMap((ranges) => ranges.map(([, end]) => end)),
  );
  const categories = new Uint8Array(maxCodePoint + 1);
  for (const [bucket, ranges] of WEIGHTED_CJK_RANGES.entries()) {
    for (const [start, end] of ranges) {
      categories.fill(bucket + 1, start, end + 1);
    }
  }
  return categories;
})();

export function estimateStringChars(text: string): number {
  return estimateStringCharsWithMinimumRawWeight(text);
}

/** Apply a raw-text safety floor without multiplying CJK adjustments twice. */
export function estimateStringCharsWithMinimumRawWeight(
  text: string,
  options: StringCharBudgetOptions = DEFAULT_BUDGET_OPTIONS,
): number {
  const minimumRawWeight = Math.max(1, options.minimumRawWeight ?? 1);
  if (minimumRawWeight !== 1 && minimumRawWeight !== 2) {
    let chars = 0;
    // Other floors retain per-ASCII-run rounding and left-to-right numeric behavior.
    for (const match of text.matchAll(ASCII_RUN_OR_NON_ASCII_CODE_POINT_RE)) {
      const segment = match[0];
      const minimumChars = Math.ceil(segment.length * minimumRawWeight);
      chars +=
        segment.charCodeAt(0) <= 0x7f
          ? minimumChars
          : Math.max(estimateStringChars(segment), minimumChars);
    }
    return chars;
  }
  const firstWeighted = text.search(WEIGHTED_CJK_RE);
  if (firstWeighted < 0) {
    return text.length * minimumRawWeight;
  }
  let common = 0;
  let rareBmp = 0;
  let twoToken = 0;
  let threeTokenSupplementary = 0;
  let supplementary = 0;
  for (let index = firstWeighted; index < text.length; index += 1) {
    let codePoint = text.charCodeAt(index);
    if (codePoint < 0x80) {
      continue;
    }
    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const low = text.charCodeAt(index + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        codePoint = 0x10000 + (codePoint - 0xd800) * 0x400 + low - 0xdc00;
        index += 1;
      }
    }
    switch (CJK_CATEGORY[codePoint]) {
      case 1:
        common += 1;
        break;
      case 2:
        rareBmp += 1;
        break;
      case 3:
        twoToken += 1;
        break;
      case 4:
        threeTokenSupplementary += 1;
        break;
      case 5:
        supplementary += 1;
        break;
      default:
        break;
    }
  }
  const commonEstimate =
    text.length * minimumRawWeight + common * (CHARS_PER_TOKEN_ESTIMATE - minimumRawWeight);
  return (
    commonEstimate +
    rareBmp * (CHARS_PER_TOKEN_ESTIMATE * 3 - minimumRawWeight) +
    twoToken * (CHARS_PER_TOKEN_ESTIMATE * 2 - minimumRawWeight) +
    threeTokenSupplementary * (CHARS_PER_TOKEN_ESTIMATE * 3 - 2 * minimumRawWeight) +
    supplementary * (CHARS_PER_TOKEN_ESTIMATE * 4 - 2 * minimumRawWeight)
  );
}

export function estimateTokensFromChars(chars: number): number {
  return Math.ceil(Math.max(0, chars) / CHARS_PER_TOKEN_ESTIMATE);
}

// Surrogate-safe UTF-16 string slicing helpers.
//
// Kept dependency-free (no node: imports) so browser/UI bundles can import them
// without dragging in filesystem/runtime code. See utils.ts, which re-exports
// these for the broad runtime surface.

function isHighSurrogate(codeUnit: number): boolean {
  return codeUnit >= 0xd800 && codeUnit <= 0xdbff;
}

function isLowSurrogate(codeUnit: number): boolean {
  return codeUnit >= 0xdc00 && codeUnit <= 0xdfff;
}

/** Moves a chunk boundary away from the middle of a UTF-16 surrogate pair. */
export function avoidTrailingHighSurrogateBreak(text: string, start: number, end: number): number {
  if (
    end <= start ||
    end >= text.length ||
    !isHighSurrogate(text.charCodeAt(end - 1)) ||
    !isLowSurrogate(text.charCodeAt(end))
  ) {
    return end;
  }
  const adjusted = end - 1;
  return adjusted > start ? adjusted : end + 1;
}

/** Slices a UTF-16 string without returning dangling surrogate halves at either edge. */
export function sliceUtf16Safe(input: string, start: number, end?: number): string {
  const len = input.length;

  let from = start < 0 ? Math.max(len + start, 0) : Math.min(start, len);
  let to = end === undefined ? len : end < 0 ? Math.max(len + end, 0) : Math.min(end, len);

  if (to <= from) {
    return "";
  }

  if (from > 0 && from < len) {
    const codeUnit = input.charCodeAt(from);
    if (isLowSurrogate(codeUnit) && isHighSurrogate(input.charCodeAt(from - 1))) {
      from += 1;
    }
  }

  if (to > 0 && to < len) {
    const codeUnit = input.charCodeAt(to - 1);
    if (isHighSurrogate(codeUnit) && isLowSurrogate(input.charCodeAt(to))) {
      to -= 1;
    }
  }

  return input.slice(from, to);
}

/** Truncates a UTF-16 string without cutting a surrogate pair in half. */
export function truncateUtf16Safe(input: string, maxLen: number): string {
  const limit = Math.max(0, Math.floor(maxLen));
  if (input.length <= limit) {
    return input;
  }
  return sliceUtf16Safe(input, 0, limit);
}

/** Truncates text and appends a marker while preserving the caller's reserved width contract. */
export function truncateWithMarker(
  value: string,
  max: number,
  options: { marker: string; reserve: number; trimEnd: boolean },
): string {
  if (value.length <= max) {
    return value;
  }
  const prefix = truncateUtf16Safe(value, max - options.reserve);
  return `${options.trimEnd ? prefix.trimEnd() : prefix}${options.marker}`;
}

import {
  estimateStringCharsWithMinimumRawWeight as estimateToolResultTextChars,
  type StringCharBudgetOptions,
} from "@openclaw/normalization-core/cjk-chars";
import { sliceUtf16Safe } from "@openclaw/normalization-core/utf16-slice";

export { estimateToolResultTextChars };

// Reuse scans across guard passes; the block owns the lifetime and text is its revision.
const toolResultTextEstimates = new WeakMap<
  object,
  { text: string; minimumRawWeight: number; chars: number }
>();

export function readPreparedToolResultTextChars(
  block: object,
  text: string,
  minimumRawWeight: number,
): number | undefined {
  const cached = toolResultTextEstimates.get(block);
  return cached?.text === text && cached.minimumRawWeight === minimumRawWeight
    ? cached.chars
    : undefined;
}

export function prepareToolResultTextChars(
  block: object,
  text: string,
  minimumRawWeight: number,
): number {
  const cached = readPreparedToolResultTextChars(block, text, minimumRawWeight);
  if (cached !== undefined) {
    return cached;
  }
  const chars = estimateToolResultTextChars(text, { minimumRawWeight });
  toolResultTextEstimates.set(block, { text, minimumRawWeight, chars });
  return chars;
}

export function isToolResultTextBlock(
  block: unknown,
): block is { type: "text" | "toolResult"; text: string; content?: unknown } {
  if (!block || typeof block !== "object") {
    return false;
  }
  const type: unknown = Reflect.get(block, "type");
  return (
    (type === "text" || type === "toolResult") && typeof Reflect.get(block, "text") === "string"
  );
}

function sliceToolResultTextBudget(
  text: string,
  maxChars: number,
  options: StringCharBudgetOptions,
  fromEnd: boolean,
): string {
  const budget = Math.max(0, Math.floor(maxChars));
  if (text.length <= budget && estimateToolResultTextChars(text, options) <= budget) {
    return text;
  }
  let best = "";
  let low = 0;
  // Every UTF-16 unit costs at least one budget unit, so longer candidates cannot fit.
  let high = Math.min(text.length, budget);
  const additive = [1, 2].includes(Math.max(1, options.minimumRawWeight ?? 1));
  let measuredLength = 0;
  let measuredChars = 0;
  while (low <= high) {
    const midpoint = Math.floor((low + high) / 2);
    const candidate = fromEnd
      ? sliceUtf16Safe(text, text.length - midpoint)
      : sliceUtf16Safe(text, 0, midpoint);
    if (additive) {
      // Safe cuts delimit complete code points, whose integer weights add.
      // Count only the changed interval; other floors need full measurement
      // because rounding belongs to each ASCII run.
      const start = Math.min(measuredLength, candidate.length);
      const end = Math.max(measuredLength, candidate.length);
      const delta = fromEnd
        ? text.slice(text.length - end, text.length - start)
        : text.slice(start, end);
      const deltaChars = estimateToolResultTextChars(delta, options);
      measuredChars += candidate.length >= measuredLength ? deltaChars : -deltaChars;
      measuredLength = candidate.length;
    } else {
      measuredChars = estimateToolResultTextChars(candidate, options);
    }
    if (measuredChars <= budget) {
      best = candidate;
      low = midpoint + 1;
    } else {
      high = midpoint - 1;
    }
  }
  return best;
}

export function sliceToolResultTextToBudget(
  text: string,
  maxChars: number,
  options: StringCharBudgetOptions = {},
): string {
  return sliceToolResultTextBudget(text, maxChars, options, false);
}

export function sliceToolResultTextTailToBudget(
  text: string,
  maxChars: number,
  options: StringCharBudgetOptions = {},
): string {
  return sliceToolResultTextBudget(text, maxChars, options, true);
}

import { truncateUtf8Prefix } from "../../../utils/utf8-truncate.js";
import {
  estimateToolResultTextChars,
  sliceToolResultTextToBudget,
} from "../../embedded-agent-runner/tool-result-text-budget.js";
import { toolResultFitsBudget, type ToolResultBudget } from "../../tool-result-limits.js";
import type { ReadToolContinuation, ReadToolDetails } from "./tool-contracts.js";
import { DEFAULT_MAX_BYTES, DEFAULT_MAX_LINES, formatSize, truncateHead } from "./truncate.js";

type BoundedReadTextPage = {
  details: Extract<ReadToolDetails, { kind: "text" | "truncated" }>;
  text: string;
};

/** Format model-visible pagination guidance from its exact structured continuation. */
export function formatReadContinuationNotice(
  continuation: ReadToolContinuation,
  maxBytes: number,
  range?: { startLine: number; totalLines: number },
): string {
  const cursor = continuation.kind === "cursor" ? `, cursor=${continuation.cursor}` : "";
  const limit = continuation.limit === undefined ? "" : `, limit=${continuation.limit}`;
  if (!range) {
    const budget = formatSize(maxBytes).replace(/\.0(?=KB)/, "");
    return `\n\n[Read output capped at ${budget} for this call. Use offset=${continuation.offset}${cursor}${limit} to continue.]`;
  }
  const label =
    continuation.kind === "cursor"
      ? `part of line ${range.startLine}`
      : `lines ${range.startLine}-${continuation.offset - 1} of ${range.totalLines}`;
  const action = continuation.kind === "cursor" ? "Use read with" : "Use";
  return `\n\n[Showing ${label} (${formatSize(maxBytes)} limit). ${action} offset=${continuation.offset}${cursor}${limit} to continue.]`;
}

/** Bound a selected text page once; legacy injected readers reuse this owner decision. */
export function createBoundedReadTextPage(params: {
  content: string;
  startLine: number;
  endLine: number;
  totalLines: number;
  /** A source page can already be partial before this tighter budget is applied. */
  continuation?: ReadToolContinuation;
  cursor?: number;
  limit?: number;
  maxBytes: number;
  pageMaxBytes?: number;
  modelBudget?: ToolResultBudget;
  /** Caller-owned framing already reserved in pageMaxBytes, never file/cursor content. */
  prefix?: string;
  adaptive?: boolean;
}): BoundedReadTextPage {
  const maxBytes = params.pageMaxBytes ?? Math.min(DEFAULT_MAX_BYTES, params.maxBytes);
  const remainingLines = params.totalLines - params.endLine;
  const limitNotice = params.continuation
    ? formatReadContinuationNotice(params.continuation, params.maxBytes)
    : params.limit !== undefined && remainingLines > 0
      ? `\n\n[${remainingLines} more line${remainingLines === 1 ? "" : "s"} in file. Use offset=${params.endLine + 1} to continue.]`
      : "";
  const contentBytes = Buffer.byteLength(params.content, "utf8");
  const resultPrefix = params.prefix ?? "";
  const completeSelectedPage = (content: string): BoundedReadTextPage => ({
    text: `${content}${limitNotice}`,
    // A complete requested slice is not EOF. Keep the next page machine-readable
    // instead of forcing Code Mode callers to parse the display-only notice.
    details: limitNotice
      ? {
          kind: "truncated",
          content,
          continuation: params.continuation ?? {
            kind: "line",
            offset: params.endLine + 1,
            limit: params.limit,
          },
          truncation: {
            truncated: true,
            truncatedBy: params.continuation?.kind === "cursor" ? "bytes" : "lines",
            totalLines: params.totalLines,
            totalBytes: contentBytes,
            outputLines:
              params.continuation?.kind === "cursor"
                ? params.continuation.offset - params.startLine
                : params.endLine - params.startLine + 1,
            outputBytes: Buffer.byteLength(content, "utf8"),
            lastLinePartial: params.continuation?.kind === "cursor",
            firstLineExceedsLimit: false,
            maxLines: params.limit ?? DEFAULT_MAX_LINES,
            maxBytes,
          },
        }
      : { kind: "text", content },
  });
  if (
    params.endLine - params.startLine < DEFAULT_MAX_LINES &&
    contentBytes + Buffer.byteLength(limitNotice, "utf8") <= maxBytes &&
    toolResultFitsBudget(`${resultPrefix}${params.content}${limitNotice}`, params.modelBudget)
  ) {
    return completeSelectedPage(params.content);
  }

  const range = params.adaptive
    ? undefined
    : { startLine: params.startLine, totalLines: params.totalLines };
  const boundedLimit = params.limit === undefined ? {} : { limit: params.limit };
  const firstLine = params.content.split("\n", 1)[0] ?? "";
  const cursorEstimate: ReadToolContinuation = {
    kind: "cursor",
    offset: params.startLine,
    cursor: (params.cursor ?? 0) + firstLine.length,
    ...boundedLimit,
  };
  const lineEstimate: ReadToolContinuation = {
    kind: "line",
    offset: params.totalLines + 1,
    ...boundedLimit,
  };
  const reservedBytes = Math.max(
    Buffer.byteLength(formatReadContinuationNotice(cursorEstimate, params.maxBytes, range), "utf8"),
    Buffer.byteLength(formatReadContinuationNotice(lineEstimate, params.maxBytes, range), "utf8"),
  );
  let prefix = truncateUtf8Prefix(params.content, Math.max(0, maxBytes - reservedBytes));
  if (params.modelBudget) {
    prefix = sliceToolResultTextToBudget(
      prefix,
      params.modelBudget.maxChars - reservedBytes - estimateToolResultTextChars(resultPrefix),
    );
    prefix = sliceToolResultTextToBudget(
      prefix,
      params.modelBudget.maxContextChars -
        reservedBytes * 2 -
        estimateToolResultTextChars(resultPrefix, { minimumRawWeight: 2 }),
      { minimumRawWeight: 2 },
    );
  }
  // Convert the fitted prefix back to a byte allowance for the existing line/cursor owner.
  // The cursor advances only over text that survives both model limits and its real footer.
  const contentBudgetBytes = Buffer.byteLength(prefix, "utf8");
  const truncation = truncateHead(params.content, { maxBytes: contentBudgetBytes });
  const truncatedBy = truncation.truncatedBy;
  if (!truncation.truncated || truncatedBy === null) {
    return completeSelectedPage(truncation.content);
  }

  let continuation: ReadToolContinuation;
  let content = truncation.content;
  if (truncation.firstLineExceedsLimit) {
    content = truncateUtf8Prefix(firstLine, contentBudgetBytes);
    continuation = {
      kind: "cursor",
      offset: params.startLine,
      cursor: (params.cursor ?? 0) + content.length,
      ...boundedLimit,
    };
  } else {
    const nextOffset = params.startLine + truncation.outputLines;
    continuation = {
      kind: "line",
      offset: nextOffset,
      ...(params.limit === undefined
        ? {}
        : { limit: Math.max(1, params.endLine - nextOffset + 1) }),
    };
  }

  const { content: _content, ...truncationDetails } = truncation;
  return {
    text: `${content}${formatReadContinuationNotice(continuation, params.maxBytes, range)}`,
    details: {
      kind: "truncated",
      content,
      truncation: {
        ...truncationDetails,
        truncated: true,
        truncatedBy,
        outputBytes: Buffer.byteLength(content, "utf8"),
        firstLineExceedsLimit: false,
        lastLinePartial: continuation.kind === "cursor",
        totalLines: params.totalLines,
      },
      continuation,
    },
  };
}

/**
 * Session tool truncation facade.
 *
 * Re-exports the shared harness truncation utilities so session tools and agent
 * harness rendering use one byte/line truncation contract.
 */
export {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  formatSize,
  truncateHead,
  type TruncationResult,
