/** Automatic live tool-result caps derived from the effective model context. */
import { AsyncLocalStorage } from "node:async_hooks";
import { resolveGlobalSingleton } from "../shared/global-singleton.js";
import { estimateToolResultTextChars } from "./embedded-agent-runner/tool-result-text-budget.js";

const MAX_TOOL_RESULT_CONTEXT_SHARE = 0.3;

export const DEFAULT_MAX_LIVE_TOOL_RESULT_CHARS = 16_000;
const LARGE_CONTEXT_MAX_LIVE_TOOL_RESULT_CHARS = 32_000;
const XL_CONTEXT_MAX_LIVE_TOOL_RESULT_CHARS = 64_000;
const LARGE_CONTEXT_TOOL_RESULT_TOKENS = 100_000;
const XL_CONTEXT_TOOL_RESULT_TOKENS = 200_000;

export function resolveAutoLiveToolResultMaxChars(contextWindowTokens: number): number {
  if (!Number.isFinite(contextWindowTokens)) {
    return DEFAULT_MAX_LIVE_TOOL_RESULT_CHARS;
  }
  const tokens = Math.floor(contextWindowTokens);
  if (tokens >= XL_CONTEXT_TOOL_RESULT_TOKENS) {
    return XL_CONTEXT_MAX_LIVE_TOOL_RESULT_CHARS;
  }
  if (tokens >= LARGE_CONTEXT_TOOL_RESULT_TOKENS) {
    return LARGE_CONTEXT_MAX_LIVE_TOOL_RESULT_CHARS;
  }
  return DEFAULT_MAX_LIVE_TOOL_RESULT_CHARS;
}

export function calculateMaxToolResultCharsWithCap(
  contextWindowTokens: number,
  hardCapChars: number,
): number {
  const maxTokens = Math.floor(contextWindowTokens * MAX_TOOL_RESULT_CONTEXT_SHARE);
  const maxChars = maxTokens * 4;
  return Math.min(maxChars, Math.max(1, hardCapChars));
}

export function resolveLiveToolResultMaxChars(params: { contextWindowTokens: number }): number {
  return calculateMaxToolResultCharsWithCap(
    params.contextWindowTokens,
    resolveAutoLiveToolResultMaxChars(params.contextWindowTokens),
  );
}

/** Fresh producer text must fit persistence/dispatch and the raw-weight context guard. */
export type ToolResultBudget = { maxChars: number; maxContextChars: number };

export function resolveToolResultContextMaxChars(contextWindowTokens: number): number {
  return Math.max(1_024, Math.floor(Math.max(1, Math.floor(contextWindowTokens)) * 2 * 0.5));
}

export function resolveToolResultBudget(
  contextWindowTokens?: number,
): ToolResultBudget | undefined {
  if (
    contextWindowTokens === undefined ||
    !Number.isFinite(contextWindowTokens) ||
    contextWindowTokens <= 0
  ) {
    return undefined;
  }
  return {
    maxChars: resolveLiveToolResultMaxChars({ contextWindowTokens }),
    maxContextChars: resolveToolResultContextMaxChars(contextWindowTokens),
  };
}

export function toolResultFitsBudget(text: string, budget?: ToolResultBudget): boolean {
  if (budget === undefined) {
    return true;
  }
  const chars = estimateToolResultTextChars(text);
  return (
    chars <= budget.maxChars &&
    // Doubling every cost bounds the raw-weight floor without rescanning each code point.
    (chars * 2 <= budget.maxContextChars ||
      estimateToolResultTextChars(text, { minimumRawWeight: 2 }) <= budget.maxContextChars)
  );
}

// The catalog's value APIs retain the complete result before transcript projection.
const fullToolResultDelivery = resolveGlobalSingleton(
  Symbol.for("openclaw.fullToolResultDelivery"),
  () => new AsyncLocalStorage<boolean>(),
);

export function runWithToolResultDelivery<T>(
  fullValue: boolean,
  action: () => Promise<T>,
): Promise<T> {
  return fullToolResultDelivery.run(fullValue, action);
}

export function assertCompleteToolResult(text: string, budget?: ToolResultBudget): void {
  if (!fullToolResultDelivery.getStore() && (!budget || !toolResultFitsBudget(text, budget))) {
    throw new Error(
      "The complete tool result cannot fit this caller's direct output budget. Invoke the tool through Code Mode to consume its full value, or split the review into smaller changes.",
    );
  }
}

/**
 * Process-local singleton helpers for registries, caches, and SDK-visible shared state.
 * Keys must be symbols so unrelated modules cannot collide on `globalThis` property names.
 */
const GLOBAL_SINGLETON_RESETS_KEY = Symbol.for("openclaw.globalSingletonLifecycleResets");

type GlobalSingletonLifecycle =
  | "close-and-restart"
  | "close-only"
  | "plugin-registry"
  | "shared-state";
type GlobalSingletonReset<T> = (value: T) => void | Promise<void>;
type RegisteredGlobalSingletonReset = {
  lifecycle: GlobalSingletonLifecycle;
  reset: () => void | Promise<void>;
};

function resolveGlobalSingletonResetRegistry(): Map<symbol, RegisteredGlobalSingletonReset> {
  const globalStore = globalThis as Record<PropertyKey, unknown>;
  const existing = globalStore[GLOBAL_SINGLETON_RESETS_KEY];
  if (existing instanceof Map) {
    return existing as Map<symbol, RegisteredGlobalSingletonReset>;
  }
  const created = new Map<symbol, RegisteredGlobalSingletonReset>();
  globalStore[GLOBAL_SINGLETON_RESETS_KEY] = created;
  return created;
}

/** Observe an existing owner's state without initializing it or registering cleanup. */
export function readGlobalSingleton(key: symbol): unknown {
  // SAFETY: Singleton slots are symbol-keyed properties owned by this registry.
  const globalStore = globalThis as Record<PropertyKey, unknown>;
  return Object.hasOwn(globalStore, key) ? globalStore[key] : undefined;
}

/** Resolves a process-local singleton for caches and registries that tolerate helper lookup. */
export function resolveGlobalSingleton<T>(
  key: symbol,
  create: () => T,
  reset?: GlobalSingletonReset<T>,
  lifecycle: GlobalSingletonLifecycle = "close-and-restart",
): T {
  const globalStore = globalThis as Record<PropertyKey, unknown>;
  let value: T;
  if (Object.hasOwn(globalStore, key)) {
    value = globalStore[key] as T;
  } else {
    value = create();
    globalStore[key] = value;
  }
  if (reset) {
    // Rent: duplicated runtime chunks share both the slot and its lifecycle owner.
    // Keep the callback registered across restarts and reset the shared value in place.
    resolveGlobalSingletonResetRegistry().set(key, {
      lifecycle,
      reset: () => reset(value),
    });
  }
  return value;
}

/** Resolves a process-local Map singleton for keyed caches backed by globalThis. */
export function resolveGlobalMap<TKey, TValue>(
  key: symbol,
  reset?: GlobalSingletonLifecycle | GlobalSingletonReset<Map<TKey, TValue>>,
  lifecycle?: GlobalSingletonLifecycle,
): Map<TKey, TValue> {
  return resolveGlobalSingleton(
    key,
    () => new Map<TKey, TValue>(),
    typeof reset === "string" ? (value) => value.clear() : reset,
    typeof reset === "string" ? reset : lifecycle,
  );
}

/** Resolves a lifecycle-owned process-local Set singleton. */
export function resolveGlobalSet<T>(key: symbol, lifecycle: GlobalSingletonLifecycle): Set<T> {
  return resolveGlobalSingleton(
    key,
    () => new Set<T>(),
    (value) => value.clear(),
    lifecycle,
  );
}

/** Resets every opt-in singleton while preserving shared object identity for the next lifecycle. */
export async function drainGlobalSingletonLifecycleState(
  event: "close" | "plugin-registry" | "restart" | "shared-state" = "close",
  options: { retainSharedState?: boolean } = {},
): Promise<void> {
  const resets = [...resolveGlobalSingletonResetRegistry().values()]
    .filter(({ lifecycle }) => {
      if (event === "shared-state") {
        return lifecycle === "shared-state";
      }
      if (lifecycle === "shared-state") {
        return event !== "plugin-registry" && !options.retainSharedState;
      }
      if (event === "plugin-registry") {
        return lifecycle === "plugin-registry";
      }
      if (lifecycle === "plugin-registry") {
        return false;
      }
      return event === "close" || lifecycle === "close-and-restart";
    })
    .map(({ reset }) => {
      try {
        return Promise.resolve(reset());
      } catch (error) {
        return Promise.reject(
          error instanceof Error
            ? error
            : new Error("Global singleton reset failed", { cause: error }),
        );
      }
    });
  const settled = await Promise.allSettled(resets);
  const errors = settled.flatMap((result) => (result.status === "rejected" ? [result.reason] : []));
  if (errors.length > 0) {
    throw new AggregateError(errors, "Failed to reset global singleton lifecycle state");
  }
}

import { Buffer } from "node:buffer";

function isContinuationByte(byte: number | undefined): boolean {
  return byte !== undefined && (byte & 0xc0) === 0x80;
}

function truncateEncodedPrefix(bytes: Buffer, maxBytes: number): string {
  let end = maxBytes;
  while (end > 0 && isContinuationByte(bytes[end])) {
    end -= 1;
  }
  return bytes.subarray(0, end).toString("utf8");
}

/** Keeps the longest UTF-8 prefix that fits within the byte limit. */
export function truncateUtf8Prefix(value: string, maxBytes: number): string {
  if (maxBytes <= 0) {
    return "";
  }
  if (value.length <= maxBytes && Buffer.byteLength(value) <= maxBytes) {
    return value;
  }
  // Only this many UTF-16 units can contribute to the retained UTF-8 prefix.
  return truncateEncodedPrefix(Buffer.from(value.slice(0, maxBytes)), maxBytes);
}

/** Keeps the longest UTF-8 suffix that fits within the byte limit. */
export function truncateUtf8Suffix(value: string, maxBytes: number): string {
  if (maxBytes <= 0) {
    return "";
  }
  if (value.length <= maxBytes && Buffer.byteLength(value) <= maxBytes) {
    return value;
  }
  // Extra UTF-16 unit shields split surrogates; fractional limits need the original byte length.
  const bytes = Buffer.from(Number.isInteger(maxBytes) ? value.slice(-maxBytes - 1) : value);
  let start = bytes.byteLength - maxBytes;
  while (start < bytes.byteLength && isContinuationByte(bytes[start])) {
    start += 1;
  }
  return bytes.subarray(start).toString("utf8");
}

